const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const laPalma = ee.Geometry.Polygon([
    [[-17.95, 28.55], [-17.75, 28.55], [-17.75, 28.70], [-17.95, 28.70], [-17.95, 28.55]]
  ]);

  const may2021 = ee.DateRange('2021-05-01', '2021-05-31');
  const dec2021 = ee.DateRange('2021-12-01', '2021-12-31');

  // 2. Data Acquisition - Sentinel-2 Surface Reflectance
  function getLavaMask(img) {
    // Use SWIR and NIR bands to detect lava (lava has low reflectance in SWIR)
    const swir1 = img.select('B11');
    const swir2 = img.select('B12');
    const nir = img.select('B8');

    // Lava typically has SWIR1 > 0.3 and NIR/SWIR ratio < 1.5
    const lavaMask = swir1.gt(0.3).and(nir.divide(swir1).lt(1.5));
    return lavaMask;
  }

  function getCloudMask(img) {
    const qa = img.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                 .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return mask;
  }

  // Get May 2021 collection (pre-eruption baseline)
  let mayCol = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(laPalma)
    .filterDate(may2021)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30))
    .map(function(img) {
      return img.updateMask(getCloudMask(img));
    });

  // Get December 2021 collection (post-eruption)
  let decCol = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(laPalma)
    .filterDate(dec2021)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30))
    .map(function(img) {
      return img.updateMask(getCloudMask(img));
    });

  // Check collection sizes
  const maySize = mayCol.size().getInfo();
  const decSize = decCol.size().getInfo();

  console.log(`May 2021 Images: ${maySize}, December 2021 Images: ${decSize}`);

  if (maySize === 0 || decSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Create composites and lava masks
  const mayComposite = mayCol.median();
  const decComposite = decCol.median();

  const mayLava = getLavaMask(mayComposite);
  const decLava = getLavaMask(decComposite);

  // Count lava pixels
  const mayStats = mayLava.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: laPalma,
    scale: 100,
    maxPixels: 1e9
  });

  const decStats = decLava.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: laPalma,
    scale: 100,
    maxPixels: 1e9
  });

  const mayCount = mayStats.get('B11').getInfo();
  const decCount = decStats.get('B11').getInfo();

  console.log(`May 2021 lava pixels: ${mayCount}`);
  console.log(`December 2021 lava pixels: ${decCount}`);

  // Check for valid pixels
  if (mayCount === null || decCount === null) {
    console.log("<answer>C3</answer>");
    return;
  }

  if (mayCount === 0 && decCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Determine if lava increased
  const increaseRatio = decCount / Math.max(mayCount, 1);
  console.log(`Lava increase ratio: ${increaseRatio.toFixed(2)}`);

  if (decCount > mayCount * 1.5) { // 50% increase threshold
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
